      "arFull": "اِتَّبِعُوْا مَاۤ اُنْزِلَ اِلَیْكُمْ مِّنْ رَّبِّكُمْ وَلَا تَتَّبِعُوْا مِنْ دُوْنِهٖۤ اَوْلِیَآءَ ؕ قَلِیْلًا مَّا تَذَكَّرُوْنَ ۟",
