      "number": 11,
      "arFull": "وَلَقَدْ خَلَقْنٰكُمْ ثُمَّ صَوَّرْنٰكُمْ ثُمَّ قُلْنَا لِلْمَلٰٓىِٕكَةِ اسْجُدُوْا لِاٰدَمَ ۖۗ فَسَجَدُوْۤا اِلَّاۤ اِبْلِیْسَ ؕ لَمْ یَكُنْ مِّنَ السّٰجِدِیْنَ ۟",
