      "arFull": "قَالَ فَاهْبِطْ مِنْهَا فَمَا یَكُوْنُ لَكَ اَنْ تَتَكَبَّرَ فِیْهَا فَاخْرُجْ اِنَّكَ مِنَ الصّٰغِرِیْنَ ۟",
      "ur": "حق تعالیٰ نے فرمایا آسمان سے اتر[1] تجھ کو کوئی حق حاصل نہیں کہ تو آسمان میں ره کر تکبر کرے سو نکل بے شک تو ذلیلوں میں سے ہے۔[2]",
      "en": "[Allāh] said, \"Descend from it [i.e., Paradise], for it is not for you to be arrogant therein. So get out; indeed, you are of the debased.\"",
