      "footnotesUr": "[1] اللہ تعالیٰ نے اس کی خواہش کے مطابق اسے مہلت عطا فرمادی جو اس کی حکمت، ارادے اور مشیت کے مطابق تھی جس کا پورا علم اسی کو ہے۔ تاہم ایک حکمت یہ نظر آتی ہے کہ اس طرح اپنے بندوں کی وہ آزمائش کرسکے گا کہ کون رحمٰن کا بندہ بنتا ہے اور کون شیطان کا پجاری؟۔",
