      "ur": "اور ہم نے حکم دیا کہ اے آدم! تم اور تمہاری بیوی جنت میں رہو۔ پھر جس جگہ سے چاہو دونوں کھاؤ، اور اس درخت کے پاس مت جاؤ[1] ورنہ تم دونوں ﻇالموں میں سے ہوجاؤ گے۔",
