      "number": 22,
      "arFull": "فَدَلّٰىهُمَا بِغُرُوْرٍ ۚ فَلَمَّا ذَاقَا الشَّجَرَةَ بَدَتْ لَهُمَا سَوْاٰتُهُمَا وَطَفِقَا یَخْصِفٰنِ عَلَیْهِمَا مِنْ وَّرَقِ الْجَنَّةِ ؕ وَنَادٰىهُمَا رَبُّهُمَاۤ اَلَمْ اَنْهَكُمَا عَنْ تِلْكُمَا الشَّجَرَةِ وَاَقُلْ لَّكُمَاۤ اِنَّ الشَّیْطٰنَ لَكُمَا عَدُوٌّ مُّبِیْنٌ ۟",
      "ur": "سو ان دونوں کو فریب سے نیچے[1] لے آیا پس ان دونوں نے جب درخت کو چکھا دونوں کی شرمگاہیں ایک دوسرے کے روبرو بے پرده ہوگئیں اور دونوں اپنے اوپر جنت کے پتے جوڑ جوڑ کر رکھنے لگے[2] اور ان کے رب نے ان کو پکارا کیا میں تم دونوں کو اس درخت سے منع نہ کرچکا تھا اور یہ نہ کہہ چکا کہ شیطان تمہارا صریح دشمن ہے؟[3]",
      "en": "So he made them fall, through deception. And when they tasted of the tree, their private parts became apparent to them, and they began to fasten together over themselves from the leaves of Paradise. And their Lord called to them, \"Did I not forbid you from that tree and tell you that Satan is to you a clear enemy?\"",
      "footnotesUr": "[1] ”تَدْلِية“ اور ”إِدْلاءٌ“ کے معنی ہیں کسی چیز کو اوپر سے نیچے چھوڑ دینا۔ گویا شیطان ان کو مرتبہ علیا سے اتار کر ممنوعہ درخت کا پھل کھانے تک لے آیا۔\n[2] یہ اس معصیت کا اثر ظاہر ہوا جو آدم (عليه السلام) وحوا سے غیر شعوری اور غیر ارادی طور پر ہوئی اور پھر دونوں مارے شرم کے جنت کے پتے جوڑ جوڑ کر اپنی شرم گاہ چھپانے لگے۔ وہب بن منبہ کہتے ہیں کہ اس سے قبل انہیں اللہ تعالیٰ کی طرف سے ایک ایسا نورانی لباس ملا ہوا تھا، جو اگرچہ غیرمرئی تھا لیکن ایک دوسرے کی شرم گاہ کے لئے ساتر (پردہ پوش) تھا۔ (ابن کثیر )\n[3] یعنی اس تنبیہ کے باوجود تم شیطان کے وسوسوں کا شکار ہوگئے۔ اس سے معلوم ہوا کہ شیطان کے جال بڑے حسین اور دلفریب ہوتے ہیں اور جن سے بچنے کے لئے بڑی کاوش ومحنت اور ہر وقت اس سے چوکنا رہنے کی ضرورت ہے۔",
      "footnotesEn": null,
