      "arFull": "فَرِیْقًا هَدٰی وَفَرِیْقًا حَقَّ عَلَیْهِمُ الضَّلٰلَةُ ؕ اِنَّهُمُ اتَّخَذُوا الشَّیٰطِیْنَ اَوْلِیَآءَ مِنْ دُوْنِ اللّٰهِ وَیَحْسَبُوْنَ اَنَّهُمْ مُّهْتَدُوْنَ ۟",
