      "arFull": "وَالَّذِیْنَ اٰمَنُوْا وَعَمِلُوا الصّٰلِحٰتِ لَا نُكَلِّفُ نَفْسًا اِلَّا وُسْعَهَاۤ ؗ اُولٰٓىِٕكَ اَصْحٰبُ الْجَنَّةِ ۚ هُمْ فِیْهَا خٰلِدُوْنَ ۟",
      "ur": "اور جو لوگ ایمان ﻻئے اور انہوں نے نیک کام کئے ہم کسی شخص کو اس کی قدرت سے زیاده کسی کا مکلف نہیں بناتے[1] وہی لوگ جنت والے ہیں اور وه اس میں ہمیشہ ہمیشہ رہیں گے۔",
      "en": "But those who believed and did righteous deeds - We charge no soul except [within] its capacity. Those are the companions of Paradise; they will abide therein eternally.",
