      "arFull": "الَّذِیْنَ یَصُدُّوْنَ عَنْ سَبِیْلِ اللّٰهِ وَیَبْغُوْنَهَا عِوَجًا ۚ وَهُمْ بِالْاٰخِرَةِ كٰفِرُوْنَ ۟ۘ",
