      "arFull": "قَالَ یٰقَوْمِ لَیْسَ بِیْ ضَلٰلَةٌ وَّلٰكِنِّیْ رَسُوْلٌ مِّنْ رَّبِّ الْعٰلَمِیْنَ ۟",
