      "arFull": "قَالَ الْمَلَاُ الَّذِیْنَ كَفَرُوْا مِنْ قَوْمِهٖۤ اِنَّا لَنَرٰىكَ فِیْ سَفَاهَةٍ وَّاِنَّا لَنَظُنُّكَ مِنَ الْكٰذِبِیْنَ ۟",
