      "number": 87,
      "arFull": "وَاِنْ كَانَ طَآىِٕفَةٌ مِّنْكُمْ اٰمَنُوْا بِالَّذِیْۤ اُرْسِلْتُ بِهٖ وَطَآىِٕفَةٌ لَّمْ یُؤْمِنُوْا فَاصْبِرُوْا حَتّٰی یَحْكُمَ اللّٰهُ بَیْنَنَا ۚ وَهُوَ خَیْرُ الْحٰكِمِیْنَ ۟",
      "ur": "اور اگر تم میں سے کچھ لوگ اس حکم پر، جس کو دے کر مجھ کو بھیجا گیا، ایمان لے آئے ہیں اور کچھ ایمان نہیں ﻻئے ہیں تو ذرا ٹھہر جاؤ! یہاں تک کہ ہمارے درمیان اللہ فیصلہ کئے دیتا ہے اور وه سب فیصلہ کرنے والوں سے بہتر ہے۔[1]",
      "en": "And if there should be a group among you who has believed in that with which I have been sent and a group that has not believed, then be patient until Allāh judges between us. And He is the best of judges.\"",
      "footnotesUr": "[1] کفر پر صبر کرنے کا حکم نہیں ہے بلکہ اس کے لئے تہدید اور سخت وعید ہے کیونکہ اللہ تعالیٰ کا فیصلہ اہل حق کا اہل باطل پر فتح و غلبہ ہی ہوتا ہے ۔ یہ ایسے ہی ہے جیسے دوسرے مقام پر فرمایا: ”فَتَرَبَّصُوٓاْ إِنَّا مَعَكُم مُّتَرَبِّصُونَ“ [التوبة:52].",
