      "number": 99,
      "arFull": "اَفَاَمِنُوْا مَكْرَ اللّٰهِ ۚ فَلَا یَاْمَنُ مَكْرَ اللّٰهِ اِلَّا الْقَوْمُ الْخٰسِرُوْنَ ۟۠",
