      "ur": "ان بستیوں کے کچھ کچھ قصے ہم آپ سے بیان کر رہے ہیں اور ان سب کے پاس ان کے پیغمبر معجزات لے کر آئے[1] ، پھر جس چیز کو انہوں نے ابتدا میں جھوٹا کہہ دیا یہ بات نہ ہوئی کہ پھر اس کو مان لیتے[2]، اللہ تعالیٰ اسی طرح کافروں کے دلوں پر بند لگا دیتا ہے۔",
      "en": "Those cities - We relate to you, [O Muḥammad], some of their news. And certainly did their messengers come to them with clear proofs, but they were not to believe in that which they had denied before.[388] Thus does Allāh seal over the hearts of the disbelievers.",
      "footnotesUr": "[1] جس طرح گزشتہ صفحات میں چند انبیاء کا ذکر گزرا۔ بینات سے مراد دلائل وبراہین اور معجزات دونوں ہیں۔ مقصد یہ ہے کہ رسولوں کے ذریعے سے جب تک ہم نے حجت تمام نہیں کر دی، ہم نے انہیں ہلاک نہیں کیا ۔ کیونکہ: «وَمَا كُنَّا مُعَذِّبِينَ حَتَّىٰ نَبۡعَثَ رَسُولٗا» [الإسراء: 15] ”جب تک ہم رسول نہیں بھیج دیتے ۔ عذاب نازل نہیں کرتے“۔\n[2] اس کا ایک مفہوم تو یہ ہے کہ یوم میثاق کو جب ان سے عہد لیا گیا تھا تو یہ اللہ کے علم میں ایمان لانے والے نہ تھے، اس لیے جب ان کے پاس رسول آئے تو اللہ کے علم کے مطابق ایمان نہیں لائے ۔ کیونکہ ان کی تقدیر میں ہی ایمان نہیں تھا جسے اللہ نے اپنے علم کے مطابق لکھ دیا تھا ۔ جس کو حدیث میں «فَكُلٌّ مُيَسَّرٌ لِمَا خُلِقَ لَهُ» (صحيح بخاري، تفسير سورة الليل) سے تعبیر کیا گیا ہے دوسرا مفہوم یہ ہے کہ جب پیغمبر ان کے پاس آئے تو وہ اس وجہ سے ان پر ایمان نہیں لائے کہ وہ اس سے قبل حق کی تکذیب کر چکے تھے ۔ گویا ابتداءً جس چیز کی وہ تکذیب کرچکے تھے، یہی گناہ ان کے عدم ایمان کا سبب بن گیا اور ایمان لانے کی توفیق ان سے سلب کر لی گئی، اسی کو اگلے جملے میں مہر لگانے سے تعبیر کیا گیا ہے ۔ «وَمَا يُشۡعِرُكُمۡ أَنَّهَآ إِذَا جَآءَتۡ لَا يُؤۡمِنُونَ، وَنُقَلِّبُ أَفۡ‍ِٔدَتَهُمۡ وَأَبۡصَٰرَهُمۡ كَمَا لَمۡ يُؤۡمِنُواْ بِهِۦٓ أَوَّلَ مَرَّةٖ» [الأنعام: 109-110]. ”اور تمہیں کیا معلوم ہے یہ تو ایسے (بدبخت) ہیں کہ ان کے پاس نشانیاں بھی آجائیں تب بھی ایمان نہ لائیں اور ہم ان کے دلوں اور آنکھوں کو الٹ دیں گے (تو) جیسے یہ اس (قرآن) پر پہلی دفعہ ایمان نہیں لائے (ویسے پھر نہ لائیں گے)“۔",
      "footnotesEn": "[388] i.e., they persistently denied every warning given them.",
