      "arFull": "قَالَ الْمَلَاُ مِنْ قَوْمِ فِرْعَوْنَ اِنَّ هٰذَا لَسٰحِرٌ عَلِیْمٌ ۟ۙ",
      "ur": "قوم فرعون میں جو سردار لوگ تھے انہوں نے کہا کہ واقعی یہ شخص بڑا ماہر جادوگر ہے۔[1]",
      "en": "Said the eminent among the people of Pharaoh, \"Indeed, this is a learned magician",
      "footnotesUr": "[1] معجزے دیکھ کر، ایمان لانے کے بجائے، فرعون کے درباریوں نے اسے جادو قرار دے کر یہ کہہ دیا کہ یہ تو بڑا ماہر جادوگر ہے جس سے اس کا مقصد تمہاری حکومت کو ختم کرنا ہے۔ کیونکہ حضرت موسیٰ (عليه السلام) کے زمانے میں جادو کا بڑا زور اور اس کا عام چلن تھا، اس لیے انہوں نے معجزات کو بھی جادو سمجھا، جن میں سرے سے انسان کا دخل ہی نہیں ہوتا۔ خالص اللہ کی مشیت سے ظہور میں آتے ہیں۔ تاہم اس عنوان سے فرعون کے درباریوں کے لیے حضرت موسیٰ (عليه السلام) کے بارے میں فرعون کو بہکانے کا موقع مل گیا۔",
