      "ur": "اور تو نے ہم میں کونسا عیب دیکھا ہے بجز اس کے کہ ہم اپنے رب کے احکام پر ایمان لے آئے[1] ، جب وه ہمارے پاس آئے۔ اے ہمارے رب! ہمارے اوپر صبر کا فیضان فرما[2] اور ہماری جان حالت اسلام پر نکال۔[3]",
      "en": "And you do not resent us except because we believed in the signs of our Lord when they came to us. Our Lord, pour upon us patience[396] and let us die as Muslims [in submission to You].\"",
      "footnotesUr": "[1] یعنی تیرے نزدیک ہمارا یہی عیب ہے ۔ جس پر تو ہم سے ناراض ہوگیا ہے اور ہمیں سزا دینے پر تل گیا ہے۔ دراں حالیکہ یہ سرے سے عیب ہی نہیں ہے۔ یہ تو خوبی ہے، بہت بڑی خوبی، کہ جب حقیقت ہمارے سامنے واضح ہوکر آگئی تو ہم نے اس کے مقابلے میں تمام دنیاوی مفادات ٹھکرا دیئے اور حقیقت کو اپنا لیا۔ پھر انہوں نے اپنا روئے سخن فرعون سے پھیر کر اللہ کی طرف کرلیا اور اس کی بارگاہ میں دست بدعا ہوگئے۔\n[2] تاکہ ہم تیرے اس دشمن کے عذاب کو برداشت کر لیں، اور حق میں متصلب اور ایمان پر ثابت قدم رہیں۔\n[3] اس دنیاوی آزمائش سے ہمارے اندر ایمان سے انحراف آئے نہ کسی اور فتنے میں ہم مبتلا ہوں۔",
      "footnotesEn": "[396] To endure the torture to which we will be subjected.",
