      "number": 138,
      "arFull": "وَجٰوَزْنَا بِبَنِیْۤ اِسْرَآءِیْلَ الْبَحْرَ فَاَتَوْا عَلٰی قَوْمٍ یَّعْكُفُوْنَ عَلٰۤی اَصْنَامٍ لَّهُمْ ۚ قَالُوْا یٰمُوْسَی اجْعَلْ لَّنَاۤ اِلٰهًا كَمَا لَهُمْ اٰلِهَةٌ ؕ قَالَ اِنَّكُمْ قَوْمٌ تَجْهَلُوْنَ ۟",
      "ur": "اور ہم نے بنی اسرائیل کو دریا سے پار اتار دیا۔ پس ان لوگوں کا ایک قوم پر گزر ہوا جو اپنے چند بتوں سے لگے بیٹھے تھے، کہنے لگے اے موسیٰ! ہمارے لیے بھی ایک معبود ایسا ہی مقرر کر دیجئے! جیسے ان کے یہ معبود ہیں۔ آپ نے فرمایا کہ واقعی تم لوگوں میں بڑی جہالت ہے۔[1]",
      "en": "And We took the Children of Israel across the sea; then they came upon a people intent in devotion to [some] idols of theirs. They [the Children of Israel] said, \"O Moses, make for us a god just as they have gods.\" He said, \"Indeed, you are a people behaving ignorantly.",
      "footnotesUr": "[1] اس سے بڑی جہالت اور نادانی کیا ہوگی کہ جس اللہ نے انہیں فرعون جیسے بڑے دشمن سے نہ صرف نجات دی، بلکہ ان کی آنکھوں کے سامنے اسے اس کے لشکر سمیت غرق کر دیا اور انہیں معجزانہ طریق سے دریا عبور کروایا۔ وہ دریا پار کرتے ہی اس اللہ کو بھول کر پتھر کے خود تراشیدہ معبود تلاش کرنے لگ گئے۔ کہتے ہیں کہ یہ بت گائے کی شکل کے تھے جو پتھر کی بنی ہوئی تھیں۔",
