      "arFull": "وَالَّذِیْنَ كَذَّبُوْا بِاٰیٰتِنَا وَلِقَآءِ الْاٰخِرَةِ حَبِطَتْ اَعْمَالُهُمْ ؕ هَلْ یُجْزَوْنَ اِلَّا مَا كَانُوْا یَعْمَلُوْنَ ۟۠",
      "ur": "اور یہ لوگ جنہوں نے ہماری آیتوں کو اور قیامت کے پیش آنے کو جھٹلایا ان کے سب کام غارت گئے۔ ان کو وہی سزا دی جائے گی جو کچھ یہ کرتے تھے۔[1]",
      "en": "Those who denied Our signs and the meeting of the Hereafter - their deeds have become worthless. Are they recompensed except for what they used to do?",
