      "number": 148,
      "arFull": "وَاتَّخَذَ قَوْمُ مُوْسٰی مِنْ بَعْدِهٖ مِنْ حُلِیِّهِمْ عِجْلًا جَسَدًا لَّهٗ خُوَارٌ ؕ اَلَمْ یَرَوْا اَنَّهٗ لَا یُكَلِّمُهُمْ وَلَا یَهْدِیْهِمْ سَبِیْلًا ۘ اِتَّخَذُوْهُ وَكَانُوْا ظٰلِمِیْنَ ۟",
      "ur": "اور موسیٰ (علیہ السلام) کی قوم نے ان کے بعد اپنے زیوروں کا ایک بچھڑا معبود ٹھہرا لیا جو کہ ایک قالب تھا جس میں ایک آواز تھی۔ کیا انہوں نے یہ نہ دیکھا کہ وه ان سے بات نہیں کرتا تھا اور نہ ان کو کوئی راه بتلاتا تھا اس کو انہوں نے معبود قرار دیا اور بڑی بے انصافی کا کام کیا۔[1]",
      "en": "And the people of Moses made, after [his departure], from their ornaments a calf - an image having a lowing sound. Did they not see that it could neither speak to them nor guide them to a way? They took it [for worship], and they were wrongdoers.",
      "footnotesUr": "[1] موسیٰ (عليه السلام) جب چالیس راتوں کے لیے کوہ طور پر گئے تو پیچھے سے سامری نامی شخص نے سونے کے زیورات اکٹھے کرکے ایک بچھڑا تیار کیا جس میں اس نے جبریل (عليه السلام) کے گھوڑے کے سموں کے نیچے کی مٹی بھی، جو اس نے سنبھال کر رکھی ہوئی تھی شامل کر دی، جس میں اللہ نے زندگی کی تاثیر رکھی تھی، جس کی وجہ سے بچھڑا کچھ کچھ بیل کی آواز نکالتا تھا۔ (گو واضح کلام کرنے اور رہنمائی کرنے سے عاجز تھا جیسا کہ قرآن کے الفاظ واضح کر رہے ہیں) اس میں اختلاف ہے کہ وہ فی الواقع گوشت پوست کا بچھڑا بن گیا تھا، یا تھا وہ سونے کا ہی۔ لیکن کسی طریقے سے اس میں ہوا داخل ہوتی تو گائے، بیل کی سی آواز اس میں سے نکلتی۔ (ابن کثیر) اس آواز سے سامری نے بنی اسرائیل کو گمراہ کیا کہ تمہارا معبود تو یہ ہے، موسیٰ (عليه السلام) بھول گئے ہیں اور وہ معبود کی تلاش میں کوہ طور پر گئے ہیں۔ ( یہ واقعہ سورۂ طٰہ میں آئے گا )",
      "footnotesEn": null,
