      "arFull": "وَاِذْ قِیْلَ لَهُمُ اسْكُنُوْا هٰذِهِ الْقَرْیَةَ وَكُلُوْا مِنْهَا حَیْثُ شِئْتُمْ وَقُوْلُوْا حِطَّةٌ وَّادْخُلُوا الْبَابَ سُجَّدًا نَّغْفِرْ لَكُمْ خَطِیْٓـٰٔتِكُمْ ؕ سَنَزِیْدُ الْمُحْسِنِیْنَ ۟",
      "ur": "اور جب ان کو حکم دیا گیا کہ تم لوگ اس آبادی میں جاکر رہو اور کھاؤ اس سے جس جگہ تم رغبت کرو اور زبان سے یہ کہتے جانا کہ توبہ ہے اور جھکے جھکے دروازه میں داخل ہونا ہم تمہاری خطائیں معاف کردیں گے۔ جو لوگ نیک کام کریں گے ان کو مزید برآں اور دیں گے۔",
      "en": "And [mention, O Muḥammad], when it was said to them, \"Dwell in this city [i.e., Jerusalem] and eat from it wherever you will and say, 'Relieve us of our burdens [i.e., sins],' and enter the gate bowing humbly; We will [then] forgive you your sins. We will increase the doers of good [in goodness and reward].\"",
