      "number": 175,
      "arFull": "وَاتْلُ عَلَیْهِمْ نَبَاَ الَّذِیْۤ اٰتَیْنٰهُ اٰیٰتِنَا فَانْسَلَخَ مِنْهَا فَاَتْبَعَهُ الشَّیْطٰنُ فَكَانَ مِنَ الْغٰوِیْنَ ۟",
      "ur": "اور ان لوگوں کو اس شخص کا حال پڑھ کر سنائیے کہ جس کو ہم نے اپنی آیتیں دیں پھر وه ان سے بالکل ہی نکل گیا، پھر شیطان اس کے پیچھے لگ گیا سو وه گمراه لوگوں میں شامل ہوگیا۔[1]",
      "en": "And recite to them, [O Muḥammad], the news of him[418] to whom We gave [knowledge of] Our signs, but he detached himself from them; so Satan pursued him, and he became of the deviators.[419]",
      "footnotesUr": "[1] مفسرین نے اسے کسی ایک متعین شخص سے متعلق قرار دیا ہے جسے کتاب الٰہی کا علم حاصل تھا لیکن پھر وہ دنیا اور شیطان کے پیچھے لگ کر گمراہ ہوگیا ۔ تاہم اس کی تعیین میں کوئی مستند بات مروی بھی نہیں۔ اس لیے اس تکلیف کی ضرورت نہیں ہے۔ یہ عام ہے اور ایسے افراد ہر امت اور ہر دور میں ہوتے رہے ہیں، جو بھی اس صفت کا حامل ہوگا، وہ اس کا مصداق قرار پائے گا۔",
      "footnotesEn": "[418] A man from the Children of Israel at the time of Moses.\n[419] Those who deliberately persist in error to the point of destruction.",
