      "number": 178,
      "arFull": "مَنْ یَّهْدِ اللّٰهُ فَهُوَ الْمُهْتَدِیْ ۚ وَمَنْ یُّضْلِلْ فَاُولٰٓىِٕكَ هُمُ الْخٰسِرُوْنَ ۟",
      "ur": "جس کو اللہ ہدایت کرتا ہے سو ہدایت پانے واﻻ وہی ہوتا ہے اور جس کو وه گمراه کر دے سو ایسے ہی لوگ خسارے میں پڑنے والے ہیں۔[1]",
      "en": "Whoever Allāh guides - he is the [rightly] guided; and whoever He sends astray[423] - it is those who are the losers.",
