      "arFull": "وَاذْكُرْ رَّبَّكَ فِیْ نَفْسِكَ تَضَرُّعًا وَّخِیْفَةً وَّدُوْنَ الْجَهْرِ مِنَ الْقَوْلِ بِالْغُدُوِّ وَالْاٰصَالِ وَلَا تَكُنْ مِّنَ الْغٰفِلِیْنَ ۟",
      "ur": "اور(اے پیغمبر ) اپنے رب کي یاد کیا کراپنے دل میں عاجزی کے ساتھ اور خوف کے ساتھ اور زور کی آواز کی نسبت کم آواز کے ساتھ صبح اور شام اور اہل غفلت میں سے مت ہونا۔",
